    private static readonly string ResumeTestGenerationPrompt = "You are an information extraction engine. You MUST NOT fabricate or normalize values beyond the rules below. \nYou will be given a single JSON object that is a C# `ResumeContentsDto`. \nYour job is to transform it into a NEW JSON object with a fixed schema.\n\n===============================================================================\nINPUT TYPE (EXACT FIELD NAMES)\n===============================================================================\nResumeContentsDto {\n  ProjectDetails: Dictionary<string, ProjectDetailsDto>,\n  BasicDetails: BasicDetailsDto | null,\n  ContactDetails: ContactDetailsDto | null,\n  WorkExperienceDetails: List<WorkExperienceDetailsDto>,\n  EducationDetails: List<EducationDetailsDto>,\n  LanguageDetails: List<LanguageDto>\n}\n\nProjectDetailsDto(\n  Name: string,\n  Description: string,\n  TechnologiesUsages: List<TechnologyUsageDto>,\n  StartDate: DateOnly,\n  LastUpdatedDate: DateOnly,\n  GithubRepoLink: string\n)\n\nTechnologyUsageDto(Name: string, Usage: float)\n\nBasicDetailsDto(\n  FirstName: string,\n  LastName: string,\n  State: string,\n  Country: string,\n  AboutLine: string\n)\n\nContactDetailsDto(\n  Email: string,\n  GithubProfileLink: string,\n  LinkedInProfileLink: string,\n  PhoneNumber: string\n)\n\nWorkExperienceDetailsDto(\n  Role: string,\n  Description: string,\n  CompanyName: string,\n  StartDate: DateOnly,\n  EndDate: DateOnly\n)\n\nEducationDetailsDto(\n  Study: string,\n  InstituteName: string,\n  State: string,\n  Country: string,\n  StartDate: DateOnly,\n  EndDate: DateOnly\n)\n\nLanguageDto(\n  Name: string,\n  Level: \"Fluent\" | \"Native\" | \"Learning\"\n)\n\n===============================================================================\nTARGET OUTPUT SCHEMA (RETURN ONLY THIS JSON OBJECT)\n===============================================================================\n{\n  \"fullName\": \"string\",\n  \"contact\": {\n    \"email\": \"string\",\n    \"phone\": \"string\",\n    \"github\": \"string\",\n    \"linkedin\": \"string\",\n    \"location\": \"string\"\n  },\n  \"summary\": \"string\",\n  \"skills\": [ \"string\" ],\n  \"workExperience\": [\n    {\n      \"role\": \"string\",\n      \"company\": \"string\",\n      \"description\": \"string\",\n      \"startDate\": \"YYYY-MM-DD\",\n      \"endDate\": \"YYYY-MM-DD\"\n    }\n  ],\n  \"projects\": [\n    {\n      \"name\": \"string\",\n      \"description\": \"string\",\n      \"technologies\": [ \"string\" ],\n      \"startDate\": \"YYYY-MM-DD\",\n      \"lastUpdatedDate\": \"YYYY-MM-DD\",\n      \"githubLink\": \"string\"\n    }\n  ],\n  \"education\": [\n    {\n      \"study\": \"string\",\n      \"institute\": \"string\",\n      \"location\": \"string\",\n      \"startDate\": \"YYYY-MM-DD\",\n      \"endDate\": \"YYYY-MM-DD\"\n    }\n  ],\n  \"languages\": [\n    { \"name\": \"string\", \"level\": \"string\" }\n  ],\n  \"meta\": {\n    \"missing\": [ \"jsonPath string\" ],\n    \"notes\": [ \"string\" ]\n  }\n}\n\n===============================================================================\nMAPPING RULES (STRICT, COPY-ONLY)\n===============================================================================\nGENERAL\n- You MUST copy values verbatim from the input. \n- The ONLY allowed derived values are:\n  1) \"fullName\" = BasicDetails.FirstName + \" \" + BasicDetails.LastName (with a single space).\n  2) \"contact.location\" = BasicDetails.State + \", \" + BasicDetails.Country.\n  3) Date formatting: convert DateOnly to \"YYYY-MM-DD\" (no time).\n- Every other string in the output MUST be an EXACT substring of the input JSON (case and spacing preserved). \n  If a value cannot be found in the input, do not invent it—omit that property or push its jsonPath to meta.missing.\n- Do NOT output placeholders like \"John Doe\", \"Acme\", \"Project Alpha\", or invented URLs.\n- Keep all top-level sections present. For lists with no items, return [] (empty array).\n- Ignore TechnologyUsageDto.Usage; include only TechnologyUsageDto.Name.\n\nCONTACT\n- email = ContactDetails.Email\n- phone = ContactDetails.PhoneNumber\n- github = ContactDetails.GithubProfileLink  (copy the FULL link exactly; do NOT extract username)\n- linkedin = ContactDetails.LinkedInProfileLink (copy exactly)\n- location = BasicDetails.State + \", \" + BasicDetails.Country\n\nSUMMARY\n- summary = BasicDetails.AboutLine (copy verbatim; do not rewrite).\n\nSKILLS\n- Build from ALL ProjectDetails.*.TechnologiesUsages[].Name across every project (dictionary VALUES).\n- Deduplicate while preserving first-seen order. \n- Output as a flat array of strings.\n\nWORK EXPERIENCE (order: most recent EndDate first; if same, most recent StartDate first)\n- For each WorkExperienceDetails item:\n  role = Role\n  company = CompanyName\n  description = Description\n  startDate = StartDate as \"YYYY-MM-DD\"\n  endDate = EndDate as \"YYYY-MM-DD\"\n\nPROJECTS (order: most recent LastUpdatedDate first)\n- Iterate over ProjectDetails dictionary VALUES (ignore keys).\n- For each project:\n  name = Name\n  description = Description\n  technologies = array of TechnologiesUsages[].Name (ignore Usage)\n  startDate = StartDate as \"YYYY-MM-DD\"\n  lastUpdatedDate = LastUpdatedDate as \"YYYY-MM-DD\"\n  githubLink = GithubRepoLink (copy exactly)\n\nEDUCATION (order: most recent EndDate first)\n- For each EducationDetails item:\n  study = Study\n  institute = InstituteName\n  location = State + \", \" + Country\n  startDate = StartDate as \"YYYY-MM-DD\"\n  endDate = EndDate as \"YYYY-MM-DD\"\n\nLANGUAGES (preserve input order)\n- For each LanguageDetails item:\n  name = Name\n  level = Level (copy the enum value string exactly)\n\n===============================================================================\nVALIDATION & META\n===============================================================================\n- Before returning, for every non-derived string in output, ensure it is an exact substring of the input JSON.\n- If ANY required source field is missing or null, DO NOT fabricate. \n  Instead, add its JSON path to meta.missing (e.g., \"ContactDetails.Email\", \"ProjectDetails['repo-api'].GithubRepoLink\").\n- meta.notes may include brief notes like \"skills deduped from 3 projects\" or \"no WorkExperienceDetails provided\".\n- It is OK if meta.* arrays are empty.\n\n===============================================================================\nOUTPUT\n===============================================================================\n- Return ONLY the final JSON object in the exact target schema (including \"meta\"). \n- No code fences, no markdown, no extra commentary.\n\n===============================================================================\nINPUT \n===============================================================================\n";
    
    private static readonly string ResumeStringGenerationPrompt = "You are an expert technical resume writer and software engineer with hiring experience.\n\nI will provide a JSON input that includes my project details, technologies used, toolchain, personal information, and development metadata. Based on this, generate a **complete, job-ready resume in JSON format** — with absolutely no missing or placeholder fields.\n\n### 🎯 Your Tasks:\n1. **Analyze and understand** my input data — projects, configs, tools, tech stack, skills, responsibilities, etc.\n2. **Infer everything** required to create a professional resume. Do NOT leave any fields for me to fill in manually.\n3. Generate all content in a **human-written, polished tone**, optimized for job applications in software development roles.\n4. Use common resume structures and sections for junior/mid-level developers.\n\n---\n\n### ✅ Output JSON Format\n\n```json\n{\n  \"basics\": {\n    \"name\": \"Full Name\",\n    \"location\": \"City, Country\",\n    \"email\": \"your@email.com\",\n    \"linkedIn\": \"https://linkedin.com/in/username\",\n    \"github\": \"https://github.com/username\",\n    \"summary\": \"A brief, high-impact summary about who I am as a developer, technologies used, and my strengths.\",\n    \"objective\": \"A 1–2 sentence tailored job objective based on my profile and experience.\"\n  },\n  \"skills\": {\n    \"languages\": [\"C#\", \"JavaScript\"],\n    \"frameworks\": [\"ASP.NET Core\", \"React\"],\n    \"tools\": [\"Docker\", \"Postman\", \"Figma\", \"Git\"],\n    \"databases\": [\"PostgreSQL\", \"SQL Server\"],\n    \"devOps\": [\"GitHub Actions\", \"Render\"],\n    \"other\": [\"JWT Auth\", \"REST APIs\", \"LINQ\", \"Clean Architecture\"],\n    \"softSkills\": [\"Problem-solving\", \"Communication\", \"Self-learning\", \"Attention to detail\", \"Teamwork\"]\n  },\n  \"education\": [\n    {\n      \"degree\": \"B.Tech in Computer Science and Engineering\",\n      \"institution\": \"Your University Name\",\n      \"location\": \"City, Country\",\n      \"startYear\": 2021,\n      \"endYear\": 2025,\n      \"highlights\": [\n        \"CGPA: 8.4/10\",\n        \"Completed projects in web development and game design\",\n        \"Actively participated in hackathons and developer communities\"\n      ]\n    }\n  ],\n  \"experience\": [\n    {\n      \"title\": \"Freelance Developer\",\n      \"organization\": \"Self-employed\",\n      \"location\": \"Remote\",\n      \"startDate\": \"2023-06\",\n      \"endDate\": \"Present\",\n      \"responsibilities\": [\n        \"Designed and developed multiple client-facing web applications using ASP.NET Core and React.\",\n        \"Collaborated with designers and backend teams to deliver high-quality software under tight deadlines.\",\n        \"Built scalable authentication systems using JWT and implemented secure REST APIs.\"\n      ]\n    }\n  ],\n  \"resumeProjects\": [\n    {\n      \"title\": \"Project Title\",\n      \"technologies\": [\"ASP.NET Core\", \"React\", \"PostgreSQL\"],\n      \"summary\": \"A 1-line summary of what the project does.\",\n      \"bulletPoints\": [\n        \"Designed a full-stack application using ASP.NET Core and React with a PostgreSQL backend.\",\n        \"Implemented secure authentication, user dashboards, and CI/CD deployment pipelines.\",\n        \"Used GitHub Actions for auto deployment and Tailwind CSS for clean UI.\"\n      ],\n      \"projectLink\": \"https://github.com/username/project\"\n    }\n  ]\n}\n";
    private static readonly string KeywordsGenerationPrompt = "";

    public async Task<string> GetAIGeneratedFullResumeAsync(ResumeContentsDto dto) {
        // List<ProjectDetailsDto> projectDetails = await userRepository.GetProjectsAsync(userId); - Try this first. Fast access from local db
        // OR
        // var projectDetails = await GetProjectsDetailsAsync();
        
        var response = await aiService.GetChatResponseAsync($"{ResumeTestGenerationPrompt}. {dto}");
        var cleanedJson = StringCleaner.GetCleanJsonString(response);
        return cleanedJson;
        
        // return JsonSerializer.Deserialize<JsonElement>(cleanedJson);
    }

    public async Task<string> GetGeneratedResumeAsync(ResumeContentsDto dto) {
        string json = JsonSerializer.Serialize(dto,  new JsonSerializerOptions { WriteIndented = true });
        return json;
    }

    public async Task<string> GetAIGeneratedKeywordsAsync(List<JsonElement> projectInsights) {
        var response = await aiService.GetChatResponseAsync($"{KeywordsGenerationPrompt}. {projectInsights}");
        // May need to clean it...   
        // var cleanedJson = StringCleaner.GetCleanCSVString(response);
        return response;
    }
    
